4	// Loading the on-device model dominates per-test cost, and most tests create a fresh
5	// RedactorService. Load once per worker and hand the same instance to every service;
6	// dispose() is a no-op so one test cannot tear the model down for the next.
7	export const realLoad = Redact.load.bind(Redact);
8	const loaded = new Map<string, Promise<Redact>>();
9	
10	vi.spyOn(Redact, "load").mockImplementation((options?: Parameters<typeof Redact.load>[0]) => {
11	  const key = JSON.stringify(options ?? {});
12	  let p = loaded.get(key);
13	  if (!p) {
14	    p = realLoad(options).then((inst) => {
15	      inst.dispose = () => {};
16	      return inst;
17	    });
18	    p.catch(() => loaded.delete(key));
19	    loaded.set(key, p);
20	  }
21	  return p;
22	});
