import { createRequire } from "node:module";
import fs from "node:fs";
const req = createRequire("/tmp/mm-spike/package.json");
const ort = req("onnxruntime-node");
const tm = await import("/tmp/mm-spike/node_modules/@huggingface/tokenizers/dist/tokenizers.mjs"); const Tokenizer = tm.Tokenizer;
const dir = "/tmp/mm-spike/model";
const tok = new Tokenizer(JSON.parse(fs.readFileSync(dir + "/tokenizer.json", "utf8")), JSON.parse(fs.readFileSync(dir + "/tokenizer_config.json", "utf8")));
const id2label = JSON.parse(fs.readFileSync(dir + "/config.json", "utf8")).id2label;

function align(text, tokens) {
  // greedy: map each sentencepiece piece to char offsets in original text
  let pos = 0; const out = [];
  for (const t of tokens) {
    if (/^\[.*\]$|^<.*>$/.test(t)) { out.push(null); continue; }
    const piece = t.replace(/^▁/, "");
    if (!piece) { out.push(null); continue; }
    const i = text.indexOf(piece, pos);
    if (i < 0 || i - pos > 8) { out.push(null); continue; }
    out.push([i, i + piece.length]); pos = i + piece.length;
  }
  return out;
}

async function run(file, text) {
  const sess = await ort.InferenceSession.create(file);
  const enc = tok.encode(text);
  const ids = enc.ids; const n = ids.length;
  const t = (a) => new ort.Tensor("int64", BigInt64Array.from(a.map(BigInt)), [1, n]);
  const feeds = { input_ids: t(ids), attention_mask: t(ids.map(() => 1)) };
  if (sess.inputNames.includes("token_type_ids")) feeds.token_type_ids = t(ids.map(() => 0));
  const t0 = performance.now(); const res = await sess.run(feeds); const ms = performance.now() - t0;
  const logits = res[sess.outputNames[0]]; const L = logits.dims[2]; const data = Array.from(logits.data, Number);
  const offs = align(text, enc.tokens);
  const spans = []; let cur = null;
  for (let i = 0; i < n; i++) {
    const row = data.slice(i * L, (i + 1) * L); const max = Math.max(...row);
    const ex = row.map((v) => Math.exp(v - max)); const sum = ex.reduce((a, b) => a + b);
    const k = row.indexOf(max); const p = ex[k] / sum; const lab = id2label[k];
    if (lab === "O" || !offs[i]) { if (lab === "O") cur = null; continue; }
    const [tag, type] = [lab[0], lab.slice(2)];
    if (tag === "B" || tag === "S" || !cur || cur.label !== type) { cur = { label: type, start: offs[i][0], end: offs[i][1], conf: p }; spans.push(cur); }
    else { cur.end = offs[i][1]; cur.conf = Math.min(cur.conf, p); }
    if (tag === "E" || tag === "S") cur = null;
  }
  return { inputs: sess.inputNames, ms: ms.toFixed(1), unaligned: offs.filter((o, i) => o === null && !/^\[|^</.test(enc.tokens[i])).length, spans: spans.map((s) => `${s.label}:${JSON.stringify(text.slice(s.start, s.end))}@${s.conf.toFixed(2)}`) };
}
