    const leftovers = fs.readdirSync(root, { recursive: true, encoding: "utf8" });
    expect(leftovers.filter((f) => f.endsWith(".tmp") || f.endsWith(".json"))).toEqual([]);
  });
  it("parses the variant env value", () => {
    expect(parseVariant(undefined)).toBe("int4");
    expect(parseVariant("fp16")).toBe("fp16");
    expect(() => parseVariant("int8")).toThrow(/PI_PII_REDACT_MASKER_VARIANT/);
  });
});

describe("backend selection", () => {
  it("rejects an unknown PI_PII_REDACT_BACKEND", async () => {
    const prev = process.env.PI_PII_REDACT_BACKEND;
    process.env.PI_PII_REDACT_BACKEND = "bogus";
    try {
      await expect(new RedactorService().getRedactInstance()).rejects.toThrow(/Unknown PI_PII_REDACT_BACKEND/);
    } finally {
      if (prev === undefined) delete process.env.PI_PII_REDACT_BACKEND;
      else process.env.PI_PII_REDACT_BACKEND = prev;
    }
  });
});
